package dev.trentdb.execution.ddl;
import dev.trentdb.ast.*; import dev.trentdb.catalog.*; import dev.trentdb.planner.*; import dev.trentdb.storage.*; import dev.trentdb.storage.wal.*; import dev.trentdb.types.*; import java.nio.file.Path; import java.util.*; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.io.TempDir; import static org.junit.jupiter.api.Assertions.*;
class DdlWalRecoveryTest { @TempDir Path dir;
 @Test void committedCreateInsertAndRepeatReplay() { try(var wal=WriteAheadLog.open(dir.resolve("a.wal"))){commit(wal,1,1,create("people"));commit(wal,2,2,insert("people",7));var catalog=new Catalog();var storage=new StorageManager();var recovery=new DdlWalRecovery(catalog,storage);var txs=wal.recoverCommittedTransactions();recovery.replay(txs);recovery.replay(txs);var table=catalog.lookupTable(recovery.startReadTransaction(),name("people"));assertEquals(1,storage.getTable(table).scanChunks().getFirst().cardinality());assertEquals(2,recovery.recoveredCommitVersion());}}
 @Test void ignoresIncompleteAndReplaysDrop() { try(var wal=WriteAheadLog.open(dir.resolve("b.wal"))){wal.appendBegin(9);wal.appendWrite(9,create("ignored"));wal.force();commit(wal,1,1,create("people"));commit(wal,2,2,DdlWalPayload.dropTable(new DropTableStatement(name("people"))));var catalog=new Catalog();var recovery=new DdlWalRecovery(catalog,new StorageManager());recovery.replay(wal.recoverCommittedTransactions());assertThrows(RuntimeException.class,()->catalog.lookupTable(recovery.startReadTransaction(),name("people")));assertEquals(2,recovery.recoveredCommitVersion());}}
 @Test void corruptOrMalformedTransactionLeavesItUnapplied() { try(var wal=WriteAheadLog.open(dir.resolve("c.wal"))){commit(wal,1,1,create("people"));wal.appendBegin(2);wal.appendWrite(2,create("bad"));wal.appendWrite(2,new byte[]{99});wal.appendCommit(2,2);wal.force();var catalog=new Catalog();var recovery=new DdlWalRecovery(catalog,new StorageManager());assertThrows(RecoveryException.class,()->recovery.replay(wal.recoverCommittedTransactions()));assertEquals("people",catalog.lookupTable(recovery.startReadTransaction(),name("people")).name());assertEquals(1,recovery.recoveredCommitVersion());}}
 private static void commit(WriteAheadLog w,long id,long v,byte[] p){w.appendBegin(id);w.appendWrite(id,p);w.appendCommit(id,v);w.force();} private static QualifiedName name(String n){return new QualifiedName(List.of(n));} private static byte[] create(String n){return DdlWalPayload.createTable(new CreateTableStatement(name(n),List.of(new ColumnDefinition("id",TypeName.BIGINT))));} private static byte[] insert(String n,long v){var t=new TableCatalogEntry(new SchemaCatalogEntry("public"),n,List.of(new ColumnCatalogEntry("id",LogicalType.BIGINT,0)));return DdlWalPayload.insert(new BoundInsertStatement(t,List.of(0),List.of(new BoundLiteralExpression(LogicalType.INTEGER,v))));}
}
